airtable_update_record.beforeRequest:
const given = request.body.fields || {};
const table = call({method: 'GET', url: '/meta/bases/' + inputs.base + '/tables'}).tables.find((t) => t.id === inputs.tableId);
const fields = {};
table.fields.forEach((field) => {
  const value = given[field.id];
  // An empty value leaves the field as it is.
  if (['singleCollaborator', 'multipleCollaborators', 'aiText'].includes(field.type) || value === undefined || value === null || value === '' || (Array.isArray(value) && value.length === 0)) return;
  if (field.type === 'multipleAttachments') { if (value) fields[field.id] = [{url: value}]; }
  else if (['multipleRecordLinks', 'multipleSelects'].includes(field.type)) { if (Array.isArray(value)) fields[field.id] = value; }
  else fields[field.id] = value;
});
request.body = {fields, typecast: true};
return request;

airtable_clean_record.beforeRequest:
const given = request.body.fields || {};
const table = call({method: 'GET', url: '/meta/bases/' + inputs.base + '/tables'}).tables.find((t) => t.id === inputs.tableId);
const fields = {};
table.fields.forEach((field) => {
  if (['singleCollaborator', 'multipleCollaborators', 'aiText'].includes(field.type) || !(field.id in given)) return;
  const value = given[field.id];
  // An empty value empties the field.
  if (field.type === 'multipleAttachments') fields[field.id] = !value || (Array.isArray(value) && value.length === 0) ? [] : [{url: value}];
  else if (['multipleRecordLinks', 'multipleSelects'].includes(field.type)) fields[field.id] = Array.isArray(value) ? value : [];
  else fields[field.id] = value === '' ? null : value;
});
request.body = {fields, typecast: true};
return request;

airtable_find_base.afterResponse:
let bases = response.bases;
let offset = response.offset;
while (offset) {
  const page = call({method: 'GET', url: '/meta/bases', query: {offset}});
  bases = bases.concat(page.bases);
  offset = page.offset;
}
const term = inputs.baseName.toLowerCase();
return bases.filter((base) => base.name.toLowerCase().includes(term));

list_records.beforeRequest:
const enc = (text) => encodeURIComponent(text).replace(/%20/g, '+').replace(/[!'()~]/g, (c) => '%' + c.charCodeAt(0).toString(16).toUpperCase());
const qs = (params) => Object.entries(params).map(([key, value]) => enc(key) + '=' + enc(String(value))).join('&');
const params = {};
if (inputs.filterByFormula) params.filterByFormula = inputs.filterByFormula;
if (inputs.view) params.view = inputs.view;
if (inputs.maxRecords) params.maxRecords = inputs.maxRecords;
if (inputs.pageSize) params.pageSize = inputs.pageSize;
if (inputs.sort) { const sort = JSON.parse(inputs.sort); (Array.isArray(sort) ? sort : [sort]).forEach((entry, index) => { params['sort[' + index + '][field]'] = entry.field; if (entry.direction) params['sort[' + index + '][direction]'] = entry.direction; }); }
if (inputs.fields) JSON.parse(inputs.fields).forEach((field, index) => { params['fields[' + index + ']'] = field; });
request.url += '?' + qs(params);
return request;

list_records.afterResponse:
const most = Number(inputs.maxRecords);
let records = response.records;
let offset = response.offset;
// Without Max Records the original gives the first page only.
while (inputs.maxRecords && offset && records.length < most) {
  const page = call({method: 'GET', url: request.url + '&offset=' + encodeURIComponent(offset)});
  records = records.concat(page.records);
  offset = page.offset;
}
if (inputs.maxRecords) records = records.slice(0, most);
return {records, count: records.length, offset: offset ?? null};

list_bases.afterResponse:
let bases = response.bases;
let offset = response.offset;
while (offset) {
  const page = call({method: 'GET', url: '/meta/bases', query: {offset}});
  bases = bases.concat(page.bases);
  offset = page.offset;
}
return {bases: bases.map((base) => ({id: base.id, name: base.name, permissionLevel: base.permissionLevel})), count: bases.length};

search_records.beforeRequest:
const enc = (text) => encodeURIComponent(text).replace(/%20/g, '+').replace(/[!'()~]/g, (c) => '%' + c.charCodeAt(0).toString(16).toUpperCase());
const qs = (params) => Object.entries(params).map(([key, value]) => enc(key) + '=' + enc(String(value))).join('&');
if (/[{}]/.test(inputs.searchField)) throw new Error('Search Field must not contain "{" or "}" — Airtable cannot escape braces inside a field reference.');
const value = String(inputs.searchValue).replace(/\\/g, '\\\\').replace(/"/g, '\\"');
const params = {filterByFormula: inputs.matchMode === 'exact' ? '{' + inputs.searchField + '}&""="' + value + '"' : 'FIND("' + value + '",{' + inputs.searchField + '})'};
if (inputs.view) params.view = inputs.view;
if (inputs.maxRecords) params.maxRecords = inputs.maxRecords;
request.url += '?' + qs(params);
return request;

search_records.afterResponse:
const most = Number(inputs.maxRecords);
let records = response.records;
let offset = response.offset;
// Without Max Records the original gives the first page only.
while (inputs.maxRecords && offset && records.length < most) {
  const page = call({method: 'GET', url: request.url + '&offset=' + encodeURIComponent(offset)});
  records = records.concat(page.records);
  offset = page.offset;
}
if (inputs.maxRecords) records = records.slice(0, most);
return {records, count: records.length};

new_record.afterResponse:
let records = response.records;
let offset = response.offset;
while (offset) {
  const query = inputs.view ? {view: inputs.view, offset} : {offset};
  const page = call({method: 'GET', url: '/' + encodeURIComponent(inputs.base) + '/' + encodeURIComponent(inputs.tableId), query, headers: {'x-airtable-application-id': inputs.base, 'x-api-version': '0.1.0'}});
  records = records.concat(page.records);
  offset = page.offset;
}
return records;
